package com.yeyamo_mobile.api.commerce_service.domain;
import org.junit.jupiter.api.*;import java.math.*;import static org.assertj.core.api.Assertions.*;import static com.yeyamo_mobile.api.commerce_service.domain.CommerceTypes.*;
class PricingEngineTest{private final PricingEngine p=new PricingEngine();
 @Test void roundsXafAndNeverProducesNegativeTotal(){var r=p.calculate(new PricingEngine.Input(new BigDecimal("1001"),BigDecimal.ZERO,new BigDecimal("49"),DiscountType.FIXED_AMOUNT,new BigDecimal("9000"),null,new BigDecimal("10"),new BigDecimal("3"),null,"XAF"));assertThat(r.totalAmount()).isEqualByComparingTo("0");assertThat(r.commissionAmount()).isEqualByComparingTo("103");assertThat(r.partnerNetAmount()).isEqualByComparingTo("0");}
 @Test void combinesPercentageAndFixedCommission(){var r=p.calculate(new PricingEngine.Input(new BigDecimal("10000"),BigDecimal.ZERO,new BigDecimal("500"),DiscountType.PERCENTAGE,new BigDecimal("10"),new BigDecimal("700"),new BigDecimal("5"),new BigDecimal("100"),null,"XOF"));assertThat(r.discountAmount()).isEqualByComparingTo("700");assertThat(r.commissionAmount()).isEqualByComparingTo("600");assertThat(r.totalAmount()).isEqualByComparingTo("9800");assertThat(r.partnerNetAmount()).isEqualByComparingTo("8700");}
 @Test void capsCommission(){var r=p.calculate(new PricingEngine.Input(new BigDecimal("10000"),BigDecimal.ZERO,BigDecimal.ZERO,null,null,null,new BigDecimal("20"),BigDecimal.ZERO,new BigDecimal("500"),"XAF"));assertThat(r.commissionAmount()).isEqualByComparingTo("500");}
 @Test void freeServiceFeeDoesNotReducePartnerNet(){var r=p.calculate(new PricingEngine.Input(new BigDecimal("10000"),BigDecimal.ZERO,new BigDecimal("500"),DiscountType.FREE_SERVICE_FEE,BigDecimal.ZERO,null,BigDecimal.ZERO,BigDecimal.ZERO,null,"XAF"));assertThat(r.totalAmount()).isEqualByComparingTo("10000");assertThat(r.partnerNetAmount()).isEqualByComparingTo("10000");}}
